/bin/zsh -lc "shasum -a 256 claim.txt protocol.txt newsletter.txt planning-minute.txt count-events.jsonl; python3 - <<'PY'
import json
from pathlib import Path
records = [json.loads(line) for line in Path('count-events.jsonl').read_text().splitlines()]
superseded = {event['supersedes'] for event in records if 'supersedes' in event}
active = {event['tray']: event['count'] for event in records if event['event_id'] not in superseded}
initial = {event['tray']: event['count'] for event in records if event['kind'] == 'count'}
for label, counts in [('initial', initial), ('corrected', active)]:
    dry = counts['D1'] + counts['D2']
    soaked = counts['S1'] + counts['S2']
    print(label, counts, {'dry': dry, 'soaked': soaked, 'dry_pct': dry/200*100, 'soaked_pct': soaked/200*100, 'extra_seedlings': soaked-dry, 'percentage_points': (soaked-dry)/200*100, 'relative_pct': (soaked-dry)/dry*100})
PY"
